_POLICE_P15 = "Helvetica-Bold"
_GRIS_P15 = colors.Color(0.14, 0.14, 0.14)
_GRAS_TRAIT = 0.012

def _style_chiffres(style):
    if str(style).lower() in ("p15", "premium"):
        return _POLICE_P15, _GRIS_P15
    return _POLICE_ECO, _GRIS_ECO

RAINBOW = [
    "#E53935", "#FF7043", "#FB8C00", "#F9A825",
    "#43A047", "#00ACC1", "#1E88E5", "#3949AB",
    "#8E24AA", "#D81B60", "#6D4C41", "#546E7A",
]
NOIR = colors.Color(0, 0, 0)
GRIS = colors.Color(0.42, 0.42, 0.42)
GRIS_CLAIR = colors.Color(0.82, 0.82, 0.82)
TRAIT_NB = "#8A8A8A"

PAGE_W, PAGE_H = A4            # PORTRAIT, comme sa planche
MAQ_W, MAQ_H = 1055.0, 1491.0
CARTES_PAGE = 10

# ⭐ 06/10 (sceau Maeva : « beaucoup d'espace blanc, on aurait pu rallonger
#    la grille ») : on REMPLIT toute la feuille A4. Comme sa maquette a le
#    même format que l'A4, remplir les deux sens ne déforme pas (0,7 % près) —
#    les tickets s'allongent, les chiffres sont plus espacés.
MARGE_X = 3 * mm
MARGE_Y = 3 * mm
FEUILLE_W = PAGE_W - 2 * MARGE_X
FEUILLE_H = PAGE_H - 2 * MARGE_Y

RANGES = [(1, 15), (16, 30), (31, 45), (46, 60), (61, 75)]
_T_SERIE = 7.0

# (bords g/d · haut/bas du cadre · haut/bas du CORPS · trait « N° » sx,sy,larg)
CARTES = [
    ([12.32, 210.43], [4.69, 492.29], [109.99, 481.56], [68.25, 26.16, 62.56]),
    ([218.01, 409.48], [4.69, 492.29], [109.99, 481.56], [271.09, 26.16, 61.61]),
    ([416.11, 603.79], [4.69, 492.29], [109.99, 481.56], [467.30, 26.16, 60.66]),
    ([611.37, 796.21], [4.69, 492.29], [109.99, 481.56], [662.56, 26.16, 59.72]),
    ([803.79, 992.42], [4.69, 492.29], [109.99, 481.56], [856.87, 26.16, 59.72]),
    ([12.32, 210.43], [514.42, 989.94], [624.41, 979.21], [68.25, 538.56, 62.56]),
    ([218.01, 408.53], [514.42, 989.94], [624.41, 979.21], [271.09, 538.56, 60.66]),
    ([416.11, 603.79], [514.42, 989.94], [624.41, 979.21], [467.30, 538.56, 60.66]),
    ([611.37, 796.21], [514.42, 989.94], [624.41, 979.21], [662.56, 538.56, 59.72]),
    ([803.79, 992.42], [514.42, 989.94], [624.41, 979.21], [856.87, 538.56, 59.72]),
]

def _split_decor():
    """Un decor par ticket (chacun ne dessine que SES traits) -> impression
    rapide, au lieu de redessiner toute la planche 10 fois par feuille."""
    buckets = [[] for _ in CARTES]
    for ct in _DECOR.split("|"):
        nums = [float(x) for x in ct.replace("m", " ").replace("l", " ").replace("c", " ").replace(",", " ").split()]
        if not nums:
            continue
        xs = nums[0::2]; ys = nums[1::2]
        cx = sum(xs) / len(xs); cy = sum(ys) / len(ys)
        placed = False
        for i, carte in enumerate(CARTES):
            bord, cadre = carte[0], carte[1]
            if bord[0] <= cx <= bord[1] and cadre[0] <= cy <= cadre[1]:
                buckets[i].append(ct); placed = True; break
        if not placed:
            best = min(range(len(CARTES)), key=lambda i: (
                (cx - (CARTES[i][0][0] + CARTES[i][0][1]) / 2.0) ** 2 +
                (cy - (CARTES[i][1][0] + CARTES[i][1][1]) / 2.0) ** 2))
            buckets[best].append(ct)
    return buckets


def _parse_into(p, contour):
    i = 0; n = len(contour)
    while i < n:
        cmd = contour[i]; j = i + 1
        while j < n and contour[j] not in "mlc":
            j += 1
        v = [float(x) for x in contour[i + 1:j].split(",")]
        if cmd == "m":
            p.moveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
        elif cmd == "l":
            p.lineTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
        else:
            p.curveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H,
                      v[2] / 1000.0 * FEUILLE_W, FEUILLE_H - v[3] / 1000.0 * FEUILLE_H,
                      v[4] / 1000.0 * FEUILLE_W, FEUILLE_H - v[5] / 1000.0 * FEUILLE_H)
        i = j
    p.close()


def _graver_planche(c):
    noms = getattr(c, "TA75formes", None)
    if noms is None:
        noms = []
        for gi, bucket in enumerate(_split_decor()):
            nom = "TA75_DECOR_%d" % gi
            c.beginForm(nom, lowerx=0, lowery=0, upperx=FEUILLE_W, uppery=FEUILLE_H)
            p = c.beginPath()
            for ct in bucket:
                _parse_into(p, ct)
            if bucket:
                c.drawPath(p, stroke=0, fill=1)
            c.endForm()
            noms.append(nom)
        c.TA75formes = noms
    return noms


def _poser_decor(c, x0, y0, couleurs):
    noms = _graver_planche(c)
    for gi in range(len(CARTES)):
        c.saveState()
        c.setFillColor(couleurs[gi])
        c.translate(x0, y0)
        c.doForm(noms[gi])
        c.restoreState()


def _gen_grille(rng):
    return [sorted(rng.sample(range(lo, hi + 1), 3)) for (lo, hi) in RANGES]


def _tirer(rng, deja):
    for _ in range(400):
        g = _gen_grille(rng)
        cle = tuple(tuple(r) for r in g)
        if cle not in deja:
            deja.add(cle); return g
    return g


def _dessiner_feuille(c, x0, y0, grilles, series, couleurs, style="eco", evenement_id=""):
    police_ch, gris_ch = _style_chiffres(style)
    _poser_decor(c, x0, y0, couleurs)

    def MX(v): return x0 + v / 1000.0 * FEUILLE_W
    def MY(v): return y0 + FEUILLE_H - v / 1000.0 * FEUILLE_H

    for gi, (bord, cadre, body, se) in enumerate(CARTES):
        col = couleurs[gi]
        grille = grilles[gi]
        tx0 = MX(bord[0]); tx1 = MX(bord[1]); CW = tx1 - tx0
        bt = MY(body[0]); bb = MY(body[1])
        body_h = bt - bb
        group_h = body_h / 5.0
        rayon = min(group_h * 0.34, CW * 0.23)
        tnum = min(group_h * 0.52, CW * 0.42, 34.0)

        for ri, nums in enumerate(grille):
            gy = bt - (ri + 1) * group_h
            n_cercle, n_grand, n_petit = nums
            cercle_x = tx0 + CW * 0.30
            cercle_y = gy + group_h * 0.58
            grand_x = tx0 + CW * 0.70
            petit_x = tx0 + CW * 0.50
            petit_y = gy + group_h * 0.10
            # bulle ronde (couleur du ticket)
            c.setStrokeColor(col); c.setLineWidth(0.7)
            c.circle(cercle_x, cercle_y, rayon, stroke=1, fill=0)
            # les 3 chiffres
            def _chiffre(val, cx, cy):
                if _sec:
                    _sec.chiffre_micro(c, val, cx, cy, tnum, gris_ch, police_ch, epaisseur=_GRAS_TRAIT)
                else:
                    c.setFillColor(gris_ch); c.setFont(police_ch, tnum)
                    c.drawCentredString(cx, cy, str(val))
            _chiffre(n_cercle, cercle_x, cercle_y - tnum * 0.34)
            _chiffre(n_grand, grand_x, cercle_y - tnum * 0.34)
            _chiffre(n_petit, petit_x, petit_y - tnum * 0.34)
            # ✒️ 06/10 (sceau Maeva : « les traits gênent ») : plus de trait
            #    de séparation — l'espacement des rangées suffit à les lire.

        # numero de serie sur le trait du N
        t = _T_SERIE
        larg = se[2] / 1000.0 * FEUILLE_W
        while t > 4.0 and pdfmetrics.stringWidth("000000", POLICE, t) > larg:
            t -= 0.25
        c.setFillColor(GRIS); c.setFont(POLICE, t)
        c.drawString(MX(se[0]), MY(se[1]), "%06d" % series[gi])
        if _sec:
            try:
                _sec.cadre_micro(c, MX(bord[0]), MY(cadre[1]), MX(bord[1]) - MX(bord[0]),
                                 MY(cadre[0]) - MY(cadre[1]), series[gi], retrait=0.7 * mm)
            except Exception:
                pass


def generer_pdf(nb_tickets=10, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", page_start=1, **_):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=A4, pageCompression=1)
    nb_tickets = max(1, min(int(nb_tickets), 10000))
    nb_pages = (nb_tickets + CARTES_PAGE - 1) // CARTES_PAGE
    rng = random.Random(770000 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    _deja = set()
    for _p in range(nb_pages):
        if nom_evenement:
            c.setFillColor(colors.black); c.setFont(POLICE, 8)
            c.drawCentredString(PAGE_W / 2, PAGE_H - 4.6 * mm, nom_evenement)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 5.5)
        c.drawRightString(PAGE_W - 5 * mm, PAGE_H - 4.6 * mm, "%03d" % no_page)
        grilles = [_tirer(rng, _deja) for _k in range(CARTES_PAGE)]
        series = [serie + k for k in range(CARTES_PAGE)]
        couleurs = [colors.HexColor(
            couleur_perso if (couleur and couleur_perso)
            else RAINBOW[(s - 1) % len(RAINBOW)] if couleur else TRAIT_NB)
            for s in series]
        _dessiner_feuille(c, MARGE_X, MARGE_Y, grilles, series, couleurs,
                          style=style, evenement_id=evenement_id)
        serie += CARTES_PAGE
        c.showPage()
        no_page += 1
    c.save(); buf.seek(0)
    return buf


if __name__ == "__main__":
    pdf = generer_pdf(nb_tickets=10, serie_start=1)
    open("test_ta75.pdf", "wb").write(pdf.read())
    print("TRIPLE ACTION 75 nouvelle maquette generee")

